/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const dismissEventName = api.context.props.payload.props_details.dismiss_event_name || 'CTA_DISMISS_EVENT';

	return {
		eventName: dismissEventName,
		eventPayload: {
            content_block: api.context.props.payload,
            actual_event: event
        }
	};
}
